import (
	"log/slog"
	"testing"
	"time"

	"example.com/remind/store"
)

// Status reads the retry map, which flush writes under d.mu, so Status
// must wait for the lock like flush does.
func TestStatusWaitsForFlushLock(t *testing.T) {
	d := NewDispatcher(store.New(time.Now), slog.New(slog.DiscardHandler), time.Now)
	d.mu.Lock()
	done := make(chan Status)
	go func() { done <- d.Status() }()
	select {
	case <-done:
		d.mu.Unlock()
		t.Fatal("Status returned while d.mu was held by flush; it reads d.retries without the lock")
	case <-time.After(100 * time.Millisecond):
	}
	d.mu.Unlock()
	select {
	case st := <-done:
		if st.Retrying != 0 {
			t.Errorf("Retrying = %d, want 0", st.Retrying)
		}
	case <-time.After(time.Second):
		t.Fatal("Status did not return after the lock was released")
	}
}
"}

